INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62071845', 62071845, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA CIANJUR', 'PENGADAAN JASA MEDIATOR', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Cianjur (Kab.)', 54000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '360 SESI @ 150.000 PER SESI', 'Mediator Eksternal melaksanakan tugas mediasi terhadap perkara yang: Ditunjuk oleh Majelis Hakim melalui penetapan; Memenuhi ketentuan pembiayaan melalui DIPA Pengadilan; Maksimal 2 (dua) sesi mediasi per perkara;Termasuk perkara prodeo atau pihak yang mendapat pembebasan biaya perkara A. Tahap Penugasan Menerima SK Mediator dari Ketua Pengadilan Menerima Surat Perintah Kerja (SPK) dari Pejabat Pembuat Komitmen (PPK). Menerima penetapan Majelis Hakim tentang penunjukan sebagai mediator. Menyesuaikan jadwal mediasi sesuai jadwal persidangan. B. Tahap Pelaksanaan Mediasi Melaksanakan proses mediasi sesuai PERMA Nomor 1 Tahun 2016 dan PERMA Nomor 3 Tahun 2022 (mediasi elektronik). Memfasilitasi dialog dan perundingan para pihak secara netral dan profesional. Menjaga prinsip kerahasiaan, independensi, dan itikad baik. Melaksanakan maksimal 2 (dua) kali sesi mediasi per perkara. C. Tahap Pelaporan Menyusun dan menyampaikan laporan hasil mediasi kepada Hakim Pemeriksa Perkara. Menyampaikan Laporan Bulanan Mediasi kepada Pengadilan Agama. Menyampaikan laporan nihil apabila tidak terdapat pelaksanaan mediasi dalam bulan berjalan', '1. Persyaratan Penyedia (Mediator Eksternal) Mediator Eksternal wajib memenuhi spesifikasi sebagai berikut: 1 Sertifikat Mediator Sertifikat sah dari lembaga terakreditasi 2 Pendidikan Minimal pendidikan terakhir (dibuktikan ijazah) 3 Identitas KTP dan NPWP 4 Administrasi CV, pas foto terbaru 5 Penawaran Biaya Surat penawaran dan rekapitulasi biaya 6. Sudah berkeluarga 2. Spesifikasi Teknis Pelaksanaan Metode Mediasi tatap muka atau elektronik Acuan PERMA 1/2016 dan PERMA 3/2022 Jumlah Sesi Maksimal 2 sesi per perkara Pembiayaan DIPA Pengadilan Pelaporan Bulanan dan hasil per perkara 3. Monitoring dan Evaluasi Dilakukan minimal 1 kali dalam 3 bulan; Dokumen monev meliputi: undangan, notulensi, daftar hadir, dan dokumentasi; Apabila tidak sesuai ketentuan, PPK dapat membatalkan SPK', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 162624);
