INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61999519', 61999519, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI KELUARGA', 'Penyediaan Tenaga Ahli IT Mobile Programmer Pengembangan Aplikasi berbasis Mobile Carik Jakarta Pelaksanaan Pendataan Keluarga Satu Pintu', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 52050000, 'June 2026', 'APBD', 1, 1, '1 orang x 6 bulan', 'Membangun dan merancang fitur atau aplikasi untuk dapat digunakan ada perangkat mobile baik IOS dan Android Mengatasi berbagai bugs dan errors yang terjadi pada aplikasi mobile Melakukan Unit Test, Integration Test, serta mendampingi User Acceptance Test setelah modul-modul dalam aplikasi dapat digunakan Melakukan debugging dan fixing terhadap program-program yang masih perlu diperbaiki Memberikan rekomendasi perubahan dan peringatan secara fungsional dan perfoma dari aplikasi yang sudah dibuat Mengikuti perkembangan teknologi terkini seputar pengembangan aplikasi mobile Membuat script pemrograman yang terstruktur sehingga mempermudah progammer lain jika ke depannya akan dikembangkan Memberikan pelatihan terhadap user dan transfer knowldege Berkolaborasi dengan Backend dan frontend serta Desain Grafis dalam pengembangan aplikasi', 'Pendidikan terakhir D4/S1 jurusan Ilmu Komputer/Sistem Informasi/ Teknik Informatika, Memiliki pengalaman kerja sebagai programmer minimal 1 tahun Memiliki kemampuan bahasa pemograman ReactJS, Boostrap, HTML 5, CSS 3, dan Java Script Memahami konsep, implementasi dan maintenance relational dan non relational database (Postgres lebih diutamakan) Memahami konsep Container, REST API, Spring Boot 2, Git Continous Integration dan Deployment menjadi nilai tambah', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 163132);
