INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62071005', 62071005, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS KEPENDUDUKAN DAN PENCATATAN SIPIL', 'Tenaga Ahli Hukum 2', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 51150000, 'November 2025', 'APBD', 1, 1, '1 orang x 3 bulan', 'a) Memberikan layanan konsultasi hukum bagi seluruh ASN terkait penyelesaian permasalahan administrasi kependudukan dalam rangka pelaksanaan pelayanan di lingkungan Dinas Kependudukan dan Pencatatan Sipil Provinsi DKI Jakarta maupun Suku Dinas Kependudukan dan Pencatatan Sipil Kab/Kota Administrasi; b) Memberikan layanan penyelesaian permasalahan hukum administrasi kependudukan termasuk melakukan mediasi dalam rangka pelaksanaan pelayanan kepada pemohon; c) Memberikan layanan pemberian pertimbangan dan opini hukum bagi seluruh ASN terkait penyelesaian permasalahan administrasi kependudukan dalam rangka pelaksanaan pelayanan di lingkungan Dinas Kependudukan dan Pencatatan Sipil Provinsi DKI Jakarta maupun Suku Dinas Kependudukan dan Pencatatan Sipil Kab/Kota Administrasi; d) Melakukan identifikasi permasalahan hukum administrasi kependudukan di lingkungan Dinas Kependudukan dan Pencatatan Sipil Provinsi DKI Jakarta maupun Suku Dinas Kependudukan dan Pencatatan Sipil Kabupaten/Kota Administrasi; e) Melakukan monitoring secara keseluruhan terhadap penyelesaian permasalahan hukum administrasi kependudukan yang telah berjalan; f) Membuat laporan bulanan dan triwulan hasil kinerja serta rekapitulasi seluruh hasil pekerjaan sebagaimana di atas; g) Menyerahkan seluruh dokumentasi hasil pekerjaan kepada PPK melalui PPTK; dan h) Menjalankan tugas dan pekerjaan lainnya sesuai dengan arahan pimpinan.', 'a) Warga Negara Indonesia b) Diutamakan memiliki Kartu Tanda Penduduk (KTP) wilayah Jabodetabek; c) Berusia 30 – 50 Tahun; d) Memiliki Nomor Pokok Wajib Pajak (NPWP); e) Pendidikan minimal Magister Hukum/ S-2 Hukum yang diutamakan sebagai berikut: IPK minimal 3.00 dalam skala 4.00 untuk Perguruan Tinggi Negeri yang Terakreditasi minimal B dari BAN-PT atau IPK minimal 3.25 dalam skala 4.00 untuk Perguruan Tinggi Swasta yang Terakreditasi minimal A dari BAN-PT. f) Memiliki sertifikasi profesi Advokat dibuktikan dengan Berita Acara Sumpah dan Kartu Tanda Advokat yang masih aktif dan terdaftar dalam organisasi profesi Advokat; g) Memiliki pengalaman kerja di bidang hukum minimal 3 tahun dibuktikan dengan Surat Pengalaman Kerja yang diterbitkan oleh Badan/Lembaga/Instansi Pemberi Kerja dan portofolio pekerjaan yang relevan; h) Pengalaman sebagaimana dimaksud juga termasuk pengalaman dalam memberikan layanan konsultasi hukum, pemberian pertimbangan dan penyelesaian permasalahan hukum; i) Diutamakan memiliki keahlian dalam memberikan pertimbangan dan opini hukum dibuktikan dengan Sertifikat/Surat Pelatihan terkait Penyusunan Opini Hukum atau Legal Opinion; j) Diutamakan memiliki keahlian dalam menyelesaikan permasalahan hukum secara non-litigasi dibuktikan dengan Sertifikat/Surat Pelatihan Mediator; k) Memiliki pengetahuan dan wawasan terkait administrasi kependudukan; l) Memiliki kemampuan berkomunikasi dan kemampuan interpersonal yang baik serta pemecahan masalah yang cepat; m) Memiliki integritas, disiplin bekerja dan mampu bekerja dalam tekanan baik individu maupun dalam tim serta dapat menyelesaikan pekerjaan sesuai target; n) Mengoperasikan Microsoft Office (Word, Excel dan PowerPoint); o) Siap bekerja di luar jam kerja.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 163708);
