INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61999376', 61999376, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI KELUARGA', 'Penyediaan Tenaga Ahli Frontend Development Coordinator Pengembangan Aplikasi berbasis Mobile Carik Jakarta Pelaksanaan Pendataan Keluarga Satu Pintu', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100650000, 'June 2026', 'APBD', 1, 1, '1 orang x 6 bulan', 'Mengoordinasikan semua aspek pengembangan antarmuka pengguna (UI) dari aplikasi atau situs web Memastikan bahwa antarmuka yang dikembangkan sesuai dengan desain, fungsionalitas, dan pengalaman pengguna (UX) yang diinginkan Membangun dan merancang fitur atau aplikasi untuk dapat digunakan ada perangkat mobile baik IOS dan Android Mengatasi berbagai bugs dan errors yang terjadi pada aplikasi mobile Melakukan Unit Test, Integration Test, serta mendampingi User Acceptance, Test setelah modul-modul dalam aplikasi dapat digunakan; Melakukan debugging dan fixing terhadap program-program yang masih perlu diperbaiki Memberikan rekomendasi perubahan dan peningkatan secara fungsional dan perfoma dari aplikasi yang sudah dibuat Mengikuti perkembangan teknologi terkini seputar pengembangan aplikasi mobile Membuat script pemrograman yang terstruktur sehingga mempermudah programmer lain jika ke depannya akan dikembangkan Memberikan pelatihan terhadap user dan transfer knowledge Berkolaborasi dengan Backend dan frontend dan desain grafis dalam pengembangan aplikasi', 'Pendidikan terakhir S1 jurusan Ilmu Komputer/Sistem Informasi/Teknik Informatika Memiliki pengalaman kerja sebagai developer minimal 6 sampai dengan 10 tahun; Memiliki pengetahuan yang kuat di lingkungan pengembangan aplikasi IOS dan Android; Menguasai Android Native Programming (Kotlin, RxJava, Dagger 2) atau IOS Native Programming (SwiftUI) Mengerti konsep dan implementasi Android Jetpack (AndroidX) Memiliki kemampuan Bahasa pemograman NodeJS, Angular dan PHP, Bahasa Golang menjadi nilai tambah; Memahami konsep rational dan non rational database; Memahami konsep Container, REST API, Git, Continous Integration dan Deployment menjadi nilai tambah Akrab dengan React Native atau Xamarin menjadi nilai tambah Mengerti konsep dari Unit Testing dan bisa mengimplementasikan Diutamakan pernah mengikuti pelatihan ISO 27001', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 163793);
