INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63146261', 63146261, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Individu Penyusunan Kajian Kebijakan Perkotaan Berkelanjutan Di Indonesia Kegiatan Prakarsa Strategis Penyusunan Rekomendasi Kebijakan Kerangka Regulasi Perkotaan Berkelanjutan Direktorat Tata Ruang, Perkotaan, Pertanahan, Dan Penanggulangan Bencana', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 123600000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Memberikan dukungan keahlian dalam analisis untuk penyempurnaan substansi kerangka regulasi Perkotaan untuk ruang lingkup: • Bentuk, Tipologi, dan Kriteria Perkotaan • Pembangunan dan pelayanan Perkotaan • Sistem Informasi Perkotaan • Perencanaan Perkotaan 2. Membantu koordinasi dengan tim pelaksana dan Jasa Konsultan Individual lain dalam pelaksanaan prakarsa strategis Kerangka Regulasi Perkotaan Berkelanjutan; 3. Membantu mengintegrasikan seluruh substansi dalam penyusunan konseptual kerangka regulasi perkotaan berkelanjutan; 4. Membantu menyiapkan bahan untuk setiap rapat/Focus Group Discussion (FGD)/diskusi/seminar/workshop lintas sektor dan lintas pelaku yang dilaksanakan; 5. Mendukung Direktorat Tata Ruang, Perkotaan, Pertanahan, dan Penanggulangan Bencana dalam kegiatan tahun anggaran 2026 6. Bertanggungjawab atas selesainya pekerjaan hingga dihasilkan laporan yang dapat diterima oleh pihak pemberi tugas dengan hasil yang memuaskan', '1. Merupakan Jasa Konsultan Individual dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 2. Memiliki NPWP dan memiliki status valid Konfirmasi Status Wajib Pajak (KSWP); 3. Memiliki pendidikan minimal S2 Perencanaan Wilayah Kota (dibuktikan dengan ijazah); 4. Memiliki pengalaman bekerja minimal 3 (tiga) tahun di bidang Pembangunan wilayah dan kota (dibuktikan dengan dokumen pendukung/surat referensi/kontrak); 5. Memiliki pengalaman pekerjaan dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 1 (satu) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; 6. Memiliki kemampuan dalam membuat proposal, laporan atau kertas kebijakan (policy paper), serta bahan presentasi (dibuktikan dengan hasil tulisan dan/atau laporan formal); dan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 165268);
