INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63392764', 63392764, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA PELABUHAN PERIKANAN', 'Perencanaan Peninggian Area Bongkar Muat UPI', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Utara (Kota)', 88294304, 'February 2026', 'APBD', 1, 1, '1 paket', 'Perencanaan peninggian area bongkar muat Unit Pengolahan Ikan (UPI) di lingkungan Unit Pengelola Pelabuhan Perikanan (UPPP), meliputi kegiatan pengumpulan data dan survei lapangan, pengukuran topografi dan elevasi eksisting, identifikasi kondisi drainase dan genangan, serta analisis kebutuhan peninggian jalan/area untuk mengurangi risiko banjir dan mendukung kelancaran aktivitas bongkar muat. Kegiatan perencanaan mencakup penyusunan konsep desain teknis peninggian jalan, penentuan elevasi rencana, struktur perkerasan, sistem drainase pendukung, serta tahapan pelaksanaan pekerjaan. Selain itu, disusun gambar rencana, perhitungan teknis, rencana anggaran biaya (RAB), dan dokumen perencanaan teknis lainnya sebagai dasar pelaksanaan konstruksi peninggian area bongkar muat UPI pada tahap selanjutnya.', 'Perencanaan peninggian area bongkar muat Unit Pengolahan Ikan (UPI) di lingkungan Unit Pengelola Pelabuhan Perikanan (UPPP) berupa peninggian jalan/area kerja, yang dilaksanakan oleh tenaga ahli berkompeten dan mencakup kegiatan teknis sebagai berikut: Survei dan Pengumpulan Data Survei kondisi eksisting area bongkar muat dan jalan akses Pengukuran topografi, elevasi, dan kemiringan permukaan Identifikasi kondisi perkerasan, tanah dasar, dan sistem drainase Inventarisasi titik genangan, banjir, dan hambatan operasional Analisis Teknis Analisis kebutuhan peninggian berdasarkan elevasi pasang, genangan, dan beban lalu lintas kendaraan bongkar muat Penentuan elevasi rencana peninggian jalan Analisis struktur perkerasan (lapis pondasi, lapis permukaan) Analisis sistem drainase permukaan dan saluran pendukung Perencanaan Teknis Penyusunan desain teknis peninggian jalan/area bongkar muat Perencanaan detail perkerasan jalan dan transisi elevasi dengan area eksisting Perencanaan saluran drainase dan pengendalian air Perencanaan tahapan pelaksanaan agar operasional UPI tetap berjalan Dokumen Perencanaan Gambar rencana (site plan, denah, potongan, detail teknis) Perhitungan teknis struktur dan perkerasan Rencana Anggaran Biaya (RAB) Spesifikasi teknis dan volume pekerjaan Laporan perencanaan teknis Standar dan Ketentuan Mengacu pada standar teknis pekerjaan jalan dan bangunan pelabuhan yang berlaku Memperhatikan aspek keselamatan kerja, lingkungan, dan kelancaran aktivitas bongkar muat Hasil pekerjaan berupa dokumen perencanaan teknis lengkap yang dapat digunakan sebagai dasar pelaksanaan konstruksi peninggian area bongkar muat UPI pada tahap selanjutnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 167168);
